import { useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

export type ThemeValue = 'light' | 'dark' | 'system';

export interface AppearanceSettings {
  theme: ThemeValue;
  scale: number;
  dense: boolean;
  font: string;
}

export interface AppearanceSettingsScreenProps {
  defaultValue?: AppearanceSettings;
  onChange?: (settings: AppearanceSettings) => void;
}

const THEME_ITEMS = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const THEME_LABELS: Record<ThemeValue, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

const FONT_OPTIONS = [
  { value: 'sans', label: 'Inter Tight', meta: 'по умолчанию' },
  { value: 'display', label: 'Fraunces', meta: 'заголовочный' },
  { value: 'mono', label: 'JetBrains Mono', meta: 'моноширинный' },
];

const INITIAL: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  font: 'sans',
};

export default function AppearanceSettingsScreen({
  defaultValue,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>(
    defaultValue ?? INITIAL,
  );

  const update = (patch: Partial<AppearanceSettings>) => {
    setSettings((prev) => {
      const next = { ...prev, ...patch };
      onChange?.(next);
      return next;
    });
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '24px',
        maxWidth: '520px',
      }}
    >
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '12px',
        }}
      >
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            color: 'var(--jx-text)',
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent" dot>
          {THEME_LABELS[settings.theme]}
        </JxBadge>
      </header>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <span style={{ color: 'var(--jx-text-2)' }}>Тема оформления</span>
        <JxToggle
          items={THEME_ITEMS}
          value={settings.theme}
          onValueChange={(value) => update({ theme: value as ThemeValue })}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(value) => update({ scale: value })}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.dense}
        onChange={(event) => update({ dense: event.target.checked })}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт интерфейса"
        placeholder="Выберите шрифт"
        options={FONT_OPTIONS}
        value={settings.font}
        onValueChange={(value) => update({ font: value })}
      />
    </section>
  );
}

